public class Main {
    public static void main(String[] args) {
        // 변수: 값을 바꿀 수 있음
        int age = 20;
        System.out.println(age);

        age = 21;
        System.out.println(age);

        // 상수: 값을 바꿀 수 없음
        final double PI = 3.14;
        // PI = 3.14159; // 에러 발생!
    }
}
